// Ambil update Telegram dan inisialisasi isolasi sesi per akun
const staticData = $getWorkflowStaticData('global');
staticData.sessions = staticData.sessions || {};
staticData.currentResolved = null;
const lastId = staticData.lastUpdateId || 0;

const updates = $json.result || [];
if (!Array.isArray(updates) || updates.length === 0) {
  return [];
}

const newUpdates = updates.filter(u => u.update_id > lastId);
if (newUpdates.length === 0) {
  return [];
}

const maxUpdateId = Math.max(...newUpdates.map(u => u.update_id));
staticData.lastUpdateId = maxUpdateId;

// Segera konfirmasi offset ke server Telegram agar poller berikutnya (tiap 10s) tidak memproses pesan ganda
try {
  await fetch(`https://api.telegram.org/botYOUR_TELEGRAM_BOT_TOKEN/getUpdates?offset=${maxUpdateId + 1}&limit=1`);
} catch (e) {}

const out = [];
for (const u of newUpdates) {
  const msg = u.message || u.channel_post;
  if (!msg) continue;

  const chatId = String(msg.chat?.id || 7937051081);
  const text = (msg.text || msg.caption || '').trim();
  const fromName = msg.from?.first_name || 'Kak';
  const username = msg.from?.username || '-';
  const hasDoc = !!msg.document;
  const fileId = msg.document?.file_id || '';
  const fileName = msg.document?.file_name || '';

  // Buat / perbarui sesi independen untuk ID Telegram ini
  if (!staticData.sessions[chatId]) {
    staticData.sessions[chatId] = {
      chat_id: chatId,
      user_name: fromName,
      username: username,
      total_reviews_analyzed: 0,
      total_files_uploaded: 0,
      total_product_scrapes: 0,
      total_shop_scrapes: 0,
      created_at: new Date().toISOString(),
      last_active: new Date().toISOString()
    };
  } else {
    staticData.sessions[chatId].last_active = new Date().toISOString();
    staticData.sessions[chatId].user_name = fromName;
  }

  const currentSession = staticData.sessions[chatId];

  // Klasifikasi intent pesan
  let intent = 'single_review';
  let shopeeUrl = '';
  let shopUrl = '';
  let shopId = '';
  let itemId = '';
  let shopeeType = '';
  let originalUrl = '';
  let isShortlink = false;

  const isShopee = /(?:shopee\.[a-z.]+|shp\.ee)/i.test(text);
  if (text.startsWith('/start') || text.startsWith('/help') || text.startsWith('/menu') || text.toLowerCase() === 'halo') {
    intent = 'command_help';
  } else if (text.startsWith('/sesi') || text.startsWith('/status') || text.startsWith('/session')) {
    intent = 'command_session';
  } else if (hasDoc && (fileName.endsWith('.xlsx') || fileName.endsWith('.xls') || fileName.endsWith('.csv'))) {
    intent = 'upload_excel';
    currentSession.total_files_uploaded += 1;
  } else if (isShopee) {
    const match = text.match(/(https?:\/\/[^\s]+|[a-zA-Z0-9_\-\.]*(?:shopee\.[a-z.]+|shp\.ee)[^\s]*)/i);
    let sUrl = match ? match[0] : text;
    if (!sUrl.startsWith('http://') && !sUrl.startsWith('https://')) {
      sUrl = 'https://' + sUrl;
    }
    originalUrl = sUrl;
    shopeeUrl = sUrl;

    // Deteksi jika link berupa Shortlink (s.shopee.co.id atau shp.ee)
    if (/s\.shopee\.[a-z.]+|shp\.ee/i.test(sUrl)) {
      isShortlink = true;
      intent = 'resolve_shortlink';
    } else {
      // Parser URL Shopee Komprehensif
      let isProduct = false;
      let cleanShopeeUrl = sUrl;
      try {
        const parsed = new URL(sUrl);
        const path = parsed.pathname;

        const dashMatch = path.match(/-i\.(\d+)\.(\d+)/);
        const prodSlashMatch = path.match(/\/product\/(\d+)\/(\d+)/);
        const slashMatch = path.match(/\/([^\/]+)\/(\d+)\/(\d+)/);

        if (dashMatch) {
          isProduct = true;
          shopId = dashMatch[1];
          itemId = dashMatch[2];
          cleanShopeeUrl = `https://shopee.co.id/product-i.${shopId}.${itemId}`;
          shopUrl = `https://shopee.co.id/shop/${shopId}`;
        } else if (prodSlashMatch) {
          isProduct = true;
          shopId = prodSlashMatch[1];
          itemId = prodSlashMatch[2];
          cleanShopeeUrl = `https://shopee.co.id/product-i.${shopId}.${itemId}`;
          shopUrl = `https://shopee.co.id/shop/${shopId}`;
        } else if (slashMatch && slashMatch[1] !== 'shop') {
          isProduct = true;
          shopId = slashMatch[2];
          itemId = slashMatch[3];
          cleanShopeeUrl = `https://shopee.co.id/product-i.${shopId}.${itemId}`;
          shopUrl = `https://shopee.co.id/shop/${shopId}`;
        } else if (path.startsWith('/product') && parsed.searchParams.has('itemId') && parsed.searchParams.has('shopId')) {
          isProduct = true;
          shopId = parsed.searchParams.get('shopId');
          itemId = parsed.searchParams.get('itemId');
          cleanShopeeUrl = `https://shopee.co.id/product-i.${shopId}.${itemId}`;
          shopUrl = `https://shopee.co.id/shop/${shopId}`;
        } else {
          isProduct = false;
          cleanShopeeUrl = `${parsed.origin}${path}`;
          shopUrl = cleanShopeeUrl;
        }
      } catch (e) {
        cleanShopeeUrl = sUrl.split('?')[0];
        shopUrl = cleanShopeeUrl;
      }

      shopeeUrl = cleanShopeeUrl;

      if (isProduct) {
        intent = 'shopee_product';
        shopeeType = 'product';
        currentSession.total_product_scrapes = (currentSession.total_product_scrapes || 0) + 1;
      } else {
        intent = 'shopee_shop';
        shopeeType = 'shop';
        currentSession.total_shop_scrapes = (currentSession.total_shop_scrapes || 0) + 1;
      }
    }
  }

  // Reset antrean akumulasi ulasan aktif untuk request baru
  staticData.currentRunReviews = [];

  out.push({
    json: {
      update_id: u.update_id,
      chat_id: Number(chatId),
      session_id: `SESI_${chatId}`,
      user_name: fromName,
      username: username,
      text: text,
      shopee_url: shopeeUrl,
      shop_url: shopUrl,
      shop_id: shopId,
      item_id: itemId,
      original_url: originalUrl || shopeeUrl,
      is_shortlink: isShortlink,
      shopee_type: shopeeType,
      intent: intent,
      has_doc: hasDoc,
      file_id: fileId,
      file_name: fileName,
      session_stats: currentSession
    }
  });
}

return out;

