const items = $input.all().map(i => i.json);
const meta = $('Link Barang Shopee?').first().json;

let inferredName = 'Produk Shopee';
if (meta.shopee_url) {
  const matchSlug = meta.shopee_url.match(/shopee\.co\.id\/([^\/\?]+)-i\.\d+\.\d+/i);
  if (matchSlug && matchSlug[1] && matchSlug[1].toLowerCase() !== 'product') {
    inferredName = decodeURIComponent(matchSlug[1]).replace(/-/g, ' ');
  }
}

let shopInfo = null;
const allScrapedReviews = [];

for (let i = 0; i < items.length; i++) {
  const it = items[i];
  if (it.type === 'shop' || it.type === 'shop_summary' || (it.follower_count !== undefined && !it.cmtid)) {
    shopInfo = {
      name: it.name || it.username || 'Toko Shopee',
      username: it.username || '-',
      rating_star: it.rating_star ? Number(it.rating_star).toFixed(2) : '4.7',
      rating_total: it.rating_total || 0,
      follower_count: it.follower_count || 0,
      response_rate: it.response_rate || 0,
      shop_url: it.shop_url || meta.shop_url || meta.shopee_url
    };
  } else if (it.type === 'review' || it.rating_star || it.comment !== undefined || it.reviewText) {
    const rawComment = (it.comment || it.reviewText || '').trim();
    const star = Number(it.rating_star || it.ratingStar) || 5;
    const cleanComment = rawComment.length > 0 ? rawComment : `Rating ${star} Bintang tanpa teks ulasan tertulis.`;

    let prodName = it.product_name || it.productTitle || inferredName;
    if (it.model_name) {
      prodName += ` [Varian: ${it.model_name}]`;
    }

    if (!shopInfo && (it.shop_name || it.shop_username)) {
      shopInfo = {
        name: it.shop_name || 'Toko Shopee',
        username: it.shop_username || '-',
        rating_star: '5.0',
        rating_total: 0,
        follower_count: 0,
        response_rate: 100,
        shop_url: `https://shopee.co.id/${it.shop_username || it.shopid || ''}`
      };
    }

    allScrapedReviews.push({
      review_id: `REV-${it.cmtid || it.reviewId || i + 1}`,
      tanggal: it.review_date ? it.review_date.split('T')[0] : (it.collected_at ? it.collected_at.split('T')[0] : new Date().toISOString().split('T')[0]),
      produk: prodName,
      komentar: cleanComment,
      rating_star: star,
      is_empty_fallback: false,
      chat_id: meta.chat_id,
      session_id: meta.session_id,
      user_name: meta.user_name,
      target_type: 'product',
      shop_info: shopInfo,
      product_url: meta.shopee_url,
      original_url: meta.original_url || meta.shopee_url,
      resolved_url: meta.shopee_url,
      is_shortlink: !!meta.is_shortlink,
      item_id: it.itemid || it.itemId || meta.item_id || '',
      shop_id: it.shopid || it.shopId || meta.shop_id || ''
    });
  }
}

// Pisahkan ulasan spesifik produk vs ulasan toko
let targetReviews = [];
let isShopFallback = false;

if (meta.item_id && allScrapedReviews.length > 0) {
  const prodSpecific = allScrapedReviews.filter(r => String(r.item_id) === String(meta.item_id));
  if (prodSpecific.length > 0) {
    targetReviews = prodSpecific;
    isShopFallback = false;
  }
}

if (targetReviews.length === 0 && allScrapedReviews.length > 0) {
  // Jika ulasan produk ini belum ada di sample, gunakan ulasan reputasi toko penjualnya!
  targetReviews = allScrapedReviews;
  isShopFallback = true;
}

if (shopInfo && targetReviews.length > 0) {
  targetReviews.forEach(r => {
    r.shop_info = shopInfo;
    r.is_shop_fallback = isShopFallback;
  });
}

if (targetReviews.length === 0) {
  return [{
    json: {
      review_id: 'PROD-NONE',
      tanggal: new Date().toISOString().split('T')[0],
      produk: inferredName,
      komentar: 'Produk Shopee aktif tanpa ulasan baru.',
      rating_star: 5,
      is_empty_fallback: true,
      is_shop_fallback: false,
      chat_id: meta.chat_id,
      session_id: meta.session_id,
      user_name: meta.user_name,
      target_type: 'product',
      shop_info: shopInfo,
      product_url: meta.shopee_url,
      original_url: meta.original_url || meta.shopee_url,
      resolved_url: meta.shopee_url,
      is_shortlink: !!meta.is_shortlink,
      shop_id: meta.shop_id || '',
      item_id: meta.item_id || ''
    }
  }];
}

return targetReviews.map(r => ({ json: r }));

