return reviews.map(r => ({ json: r }));

const msg = $input.first().json;
return [{
  json: {
    review_id: 'REV-DIRECT-001',
    tanggal: new Date().toISOString().split('T')[0],
    produk: 'Ulasan Langsung',
    komentar: msg.text,
    rating_star: 5,
    is_empty_fallback: false,
    chat_id: msg.chat_id,
    session_id: msg.session_id,
    user_name: msg.user_name,
    target_type: 'single_text'
  }
}];

const items = $input.all().map(i => i.json);

if (!items || items.length === 0) {
  return [{ json: { needs_ai: false, all_reviews: [], prompt_text: '', text_reviews: [] } }];
}

if (items.length === 1 && items[0].is_empty_fallback) {
  return [{ json: { needs_ai: false, all_reviews: items, prompt_text: '', text_reviews: [] } }];
}

const allReviews = [];
const textReviewsToAnalyze = [];

for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const star = Number(item.rating_star) || 5;
  const rawComment = (item.komentar || '').trim();

  // Cek apakah ulasan hanya rating bintang (tanpa teks ulasan tertulis nyata)
  const isStarOnly = !rawComment || 
                     rawComment.length <= 3 || 
                     rawComment.startsWith('Rating ') || 
                     rawComment.toLowerCase().includes('tanpa teks ulasan');

  if (isStarOnly) {
    // Klasifikasi Instan 0ms berbasis Star Rating
    let sentimen = 'Positif';
    let skor = 0.90;
    let topik = 'Kepuasan Rating Bintang';
    let ringkasan = `Rating ${star} bintang dari pembeli`;

    if (star <= 2) {
      sentimen = 'Negatif';
      skor = 0.15;
      topik = 'Keluhan Rating Bintang';
      ringkasan = `Rating rendah ${star} bintang dari pembeli`;
    } else if (star === 3) {
      sentimen = 'Netral';
      skor = 0.50;
      topik = 'Rating Bintang Netral';
      ringkasan = `Rating netral ${star} bintang`;
    }

    allReviews.push({
      ...item,
      sentimen: sentimen,
      skor: skor,
      topik: topik,
      ringkasan_aspek: ringkasan,
      engine_dipakai: 'Klasifikasi Instan Rating'
    });
  } else {
    // Ulasan ada teks pembeli nyata -> kirim ke batch AI (maksimal 10 ulasan teks teratas untuk kecepatan puncak)
    if (textReviewsToAnalyze.length < 10) {
      textReviewsToAnalyze.push({
        id: item.review_id || `REV-${i+1}`,
        produk: item.produk || 'Produk Shopee',
        rating: star,
        komentar: rawComment.substring(0, 250)
      });
    }
    allReviews.push({
      ...item,
      sentimen: star >= 4 ? 'Positif' : (star <= 2 ? 'Negatif' : 'Netral'),
      skor: star >= 4 ? 0.9 : (star <= 2 ? 0.2 : 0.5),
      topik: 'Kualitas Produk',
      ringkasan_aspek: rawComment.substring(0, 100),
      engine_dipakai: 'Antrean AI'
    });
  }
}

if (textReviewsToAnalyze.length > 0) {
  const prompt = `Kamu adalah AI Review Analyst profesional. Analisis daftar ${textReviewsToAnalyze.length} ulasan pembeli berikut secara objektif:
${JSON.stringify(textReviewsToAnalyze, null, 2)}

Kembalikan HANYA JSON Array valid dengan format:
[
  {
    "id": "string ID ulasan",
    "sentimen": "Positif" | "Negatif" | "Netral",
    "skor": 0.0 sampai 1.0,
    "topik": "string topik singkat",
    "ringkasan_aspek": "string intisari ulasan"
  }
]`;

  return [{
    json: {
      needs_ai: true,
      prompt_text: prompt,
      all_reviews: allReviews,
      text_reviews: textReviewsToAnalyze
    }
  }];
}

return [{
  json: {
    needs_ai: false,
    prompt_text: '',
    all_reviews: allReviews,
    text_reviews: []
  }
}];

