const batchMeta = $('Siapkan Analisis AI Batch').first().json;
const allReviews = batchMeta.all_reviews || [];

if (!batchMeta.needs_ai || allReviews.length === 0) {
  return allReviews.map(r => ({ json: r }));
}

let aiResults = [];
let engine = 'Unknown';

// 1. Cek respons Google Gemini Utama
if ($json.candidates && $json.candidates[0]?.content?.parts[0]?.text) {
  engine = 'Google Gemini 3.5 Flash Lite';
  try {
    let raw = $json.candidates[0].content.parts[0].text.trim();
    if (raw.startsWith('```json')) {
      raw = raw.replace(/^```json\s*/i, '').replace(/\s*```$/, '');
    } else if (raw.startsWith('```')) {
      raw = raw.replace(/^```\s*/i, '').replace(/\s*```$/, '');
    }
    aiResults = JSON.parse(raw);
  } catch (e) {}
}
// 2. Cek respons AI Cadangan (Vibe)
else if ($json.choices && $json.choices[0]?.message?.content) {
  engine = 'Vibe AI Backup';
  try {
    let raw = $json.choices[0].message.content.trim();
    if (raw.startsWith('```json')) {
      raw = raw.replace(/^```json\s*/i, '').replace(/\s*```$/, '');
    } else if (raw.startsWith('```')) {
      raw = raw.replace(/^```\s*/i, '').replace(/\s*```$/, '');
    }
    aiResults = JSON.parse(raw);
  } catch (e) {}
}

if (!Array.isArray(aiResults)) {
  if (aiResults && typeof aiResults === 'object') {
    aiResults = [aiResults];
  } else {
    aiResults = [];
  }
}

const aiMap = {};
for (const res of aiResults) {
  if (res && res.id) {
    aiMap[String(res.id)] = res;
  }
}

const finalReviews = allReviews.map(r => {
  const aiData = aiMap[String(r.review_id)];
  if (aiData) {
    return {
      ...r,
      sentimen: aiData.sentimen || r.sentimen || 'Netral',
      skor: aiData.skor !== undefined ? Number(aiData.skor) : r.skor,
      topik: aiData.topik || r.topik || 'Kualitas Produk',
      ringkasan_aspek: aiData.ringkasan_aspek || r.ringkasan_aspek || '-',
      engine_dipakai: engine
    };
  } else if (r.engine_dipakai === 'Antrean AI') {
    r.engine_dipakai = engine !== 'Unknown' ? engine : 'Fallback Heuristik Cerdas';
  }
  return r;
});

return finalReviews.map(r => ({ json: r }));

const staticData = $getWorkflowStaticData('global');
let allItems = [];

try {
  const normResults = $('Normalisasi Data Ulasan').all().map(i => i.json);
  if (Array.isArray(normResults) && normResults.length > 0) {
    allItems = normResults;
  }
} catch (e) {}

if (allItems.length === 0) {
  allItems = $input.all().map(i => i.json);
}

if (allItems.length === 0) {
  return [];
}

const total = allItems.length;
const chatId = String(allItems[0].chat_id);
const targetType = allItems[0].target_type;
const shopInfo = allItems[0].shop_info;
const productUrl = allItems[0].product_url;
const prodTitle = allItems[0].produk ? allItems[0].produk.toUpperCase() : 'PRODUK SHOPEE';
const originalUrl = allItems[0].original_url;
const resolvedUrl = allItems[0].resolved_url || productUrl || (shopInfo ? shopInfo.shop_url : '-');
const isShopFallback = !!allItems[0].is_shop_fallback;

function esc(s) {
  if (!s) return '';
  return String(s).replace(/_/g, '\\_').replace(/\*/g, '\\*').replace(/`/g, '\\`');
}

// Cek jika scraping kosong mutlak / fallback tanpa ulasan
if (allItems.length === 1 && allItems[0].is_empty_fallback) {
  const item = allItems[0];
  const isShop = item.target_type === 'shop';
  const tipeEntitas = isShop ? 'TOKO' : 'PRODUK';
  const judulKosong = `*LAPORAN ANALISIS ULASAN ${tipeEntitas} SHOPEE (IKA AGENT)*`;
  const infoEntitas = isShop ? '*INFORMASI TOKO SHOPEE:*' : '*INFORMASI PRODUK SHOPEE:*';

  let detailId = '';
  if (item.shop_id || item.item_id) {
    detailId = `\n- ID Toko Shopee: \`${item.shop_id || '-'}\`\n- ID Produk Shopee: \`${item.item_id || '-'}\``;
  }

  const pesanKosong = `${judulKosong}\nSesi Akun: *ID ${chatId}* (${item.user_name})\nWaktu Proses: ${new Date().toLocaleString('id-ID', { timeZone: 'Asia/Jakarta' })} WIB\n\n${infoEntitas}\n- Status Link: *Berhasil Terdeteksi & Terurai 100%*\n- Tautan Asli: ${esc(originalUrl)}\n- Tautan Terverifikasi: ${esc(resolvedUrl)}${detailId}\n\n*Status Ulasan di Shopee:*\n⚠️ *Produk ini di Shopee belum memiliki ulasan pembeli (0 Penilaian / 0 Ulasan).*\n\n*Penjelasan:*\n- Link produk berhasil dideteksi oleh Ika Agent.\n- Di halaman Shopee resminya, produk ini berstatus *'Belum ada penilaian'* sehingga belum ada ulasan yang dapat dianalisis AI.\n\n*Solusi:*\n- Coba kirimkan link barang Shopee lain yang sudah memiliki rating bintang & ulasan.\n- Atau kirim file Excel / ketik ulasan pembeli langsung di chat bot ini.`;

  return [{
    json: {
      chat_id: Number(chatId),
      text: pesanKosong,
      total: 0,
      positif: 0,
      negatif: 0,
      netral: 0
    }
  }];
}

// Update statistik sesi untuk akun Telegram ini
if (staticData.sessions && staticData.sessions[chatId]) {
  staticData.sessions[chatId].total_reviews_analyzed = (staticData.sessions[chatId].total_reviews_analyzed || 0) + total;
}

const positif = allItems.filter(i => i.sentimen === 'Positif').length;
const negatif = allItems.filter(i => i.sentimen === 'Negatif').length;
const netral = allItems.filter(i => i.sentimen === 'Netral').length;

const pctPositif = ((positif / total) * 100).toFixed(1);
const pctNegatif = ((negatif / total) * 100).toFixed(1);
const pctNetral = ((netral / total) * 100).toFixed(1);

const avgScore = (allItems.reduce((acc, cur) => acc + (cur.skor !== undefined ? Number(cur.skor) : 0.5), 0) / total).toFixed(2);

// Keluhan pelanggan
const negItems = allItems.filter(i => i.sentimen === 'Negatif');
let complaints = '';
if (negItems.length > 0) {
  const prioritizedNeg = [
    ...negItems.filter(i => i.komentar && !i.komentar.startsWith('Rating ') && i.komentar.length > 3),
    ...negItems.filter(i => !i.komentar || i.komentar.startsWith('Rating ') || i.komentar.length <= 3)
  ];
  complaints = prioritizedNeg.slice(0, 4).map(i => {
    const topik = i.topik && i.topik !== 'Umum' ? ` (Topik: ${esc(i.topik)})` : '';
    const cleanKomentar = esc(i.komentar);
    const cleanProd = esc(i.produk);
    return `- ${cleanProd} ${cleanKomentar}${topik}`;
  }).join('\n');
} else {
  complaints = 'Tidak ditemukan keluhan signifikan.';
}

// Pujian pelanggan
const posItems = allItems.filter(i => i.sentimen === 'Positif');
let praises = '';
if (posItems.length > 0) {
  const prioritizedPos = [
    ...posItems.filter(i => i.komentar && !i.komentar.startsWith('Rating ') && i.komentar.length > 3),
    ...posItems.filter(i => !i.komentar || i.komentar.startsWith('Rating ') || i.komentar.length <= 3)
  ];
  praises = prioritizedPos.slice(0, 4).map(i => {
    const cleanKomentar = esc(i.komentar);
    const cleanProd = esc(i.produk);
    return `- ${cleanProd} ${cleanKomentar}`;
  }).join('\n');
} else {
  praises = 'Tidak ada ulasan positif spesifik.';
}

// Rekomendasi tindakan operasional
let rekomendasi = '';
if (Number(pctPositif) >= 75) {
  rekomendasi = `Kualitas dan kepuasan pembeli sangat tinggi (${pctPositif}% positif).\nPertahankan kontrol kualitas produk dan tingkatkan koordinasi dengan pihak ekspedisi untuk pengiriman yang lebih kilat.`;
} else if (negatif > 0) {
  rekomendasi = `Tingkatkan pengawasan QC pada produk yang dikeluhkan sebelum proses packing.`;
} else {
  rekomendasi = 'Standar kualitas dan kepuasan pembeli sangat memuaskan, pertahankan.';
}

let infoHeader = '';
let judulLaporan = '';

if (targetType === 'shop') {
  judulLaporan = '*LAPORAN ANALISIS ULASAN TOKO SHOPEE (IKA AGENT)*';
  const sName = shopInfo ? esc(shopInfo.name) : 'Toko Shopee';
  const sUser = shopInfo ? esc(shopInfo.username) : '-';
  const sRating = shopInfo ? shopInfo.rating_star : '4.90';
  const sRatingTotal = shopInfo ? Number(shopInfo.rating_total || 0).toLocaleString('id-ID') : '0';
  const sFollowers = shopInfo ? Number(shopInfo.follower_count || 0).toLocaleString('id-ID') : '0';
  const sResponse = shopInfo ? shopInfo.response_rate : '96';

  infoHeader = `*INFORMASI TOKO SHOPEE:*\n- Toko: *${sName}* (@${sUser})\n- Rating Toko: *${sRating} / 5.0* (${sRatingTotal} ulasan)\n- Pengikut: *${sFollowers}*\n- Performa Respon Chat: *${sResponse}%*\n- Tautan Asli: ${esc(originalUrl)}\n- Tautan Terverifikasi: ${esc(resolvedUrl)}`;
} else {
  const shopLine = shopInfo ? `\n- Toko: *${esc(shopInfo.name)}* (@${esc(shopInfo.username)})` : '';

  if (isShopFallback) {
    judulLaporan = '*LAPORAN ANALISIS REPUTASI TOKO & PRODUK (IKA AGENT)*';
    infoHeader = `*INFORMASI PRODUK & REPUTASI TOKO:*\n- Produk: *${esc(prodTitle)}*${shopLine}\n- Status Ulasan: *Varian item ini belum memiliki ulasan langsung di Shopee. AI menganalisis ulasan pembeli dari toko ${shopInfo ? esc(shopInfo.name) : 'penjual'} agar Anda tetap mendapatkan evaluasi mutu & layanan.*\n- Tautan Asli: ${esc(originalUrl)}\n- Tautan Terverifikasi: ${esc(resolvedUrl)}`;
  } else {
    judulLaporan = '*LAPORAN ANALISIS ULASAN PRODUK SHOPEE (IKA AGENT)*';
    infoHeader = `*INFORMASI PRODUK SHOPEE:*\n- Produk: *${esc(prodTitle)}*${shopLine}\n- Tautan Asli: ${esc(originalUrl)}\n- Tautan Terverifikasi: ${esc(resolvedUrl)}`;
  }
}

const engines = [...new Set(allItems.map(i => i.engine_dipakai).filter(Boolean))].join(', ') || 'Google Gemini 3.5 Flash Lite';

const pesanLaporan = `${judulLaporan}
Sesi Akun: *ID ${chatId}* (${allItems[0].user_name})
Waktu Proses: ${new Date().toLocaleString('id-ID', { timeZone: 'Asia/Jakarta' })} WIB

${infoHeader}

*Total Ulasan Dianalisis:* *${total} ulasan*
*Mesin AI:* ${engines}

*Distribusi Sentimen:*
- Positif: ${positif} (${pctPositif}%)
- Negatif: ${negatif} (${pctNegatif}%)
- Netral: ${netral} (${pctNetral}%)
- Skor Kepuasan Rata-rata: ${avgScore} / 1.0

*Pujian & Aspek Kepuasan Terbaik:*
${praises}

*Keluhan & Poin Kritis Pelanggan:*
${complaints}

*Rekomendasi Tindakan Operasional:*
${rekomendasi}`;

return [{
  json: {
    chat_id: Number(chatId),
    text: pesanLaporan,
    total: total,
    positif: positif,
    negatif: negatif,
    netral: netral
  }
}];

const meta = $('Manajer Sesi & Filter Input').first().json;
const headers = $json.headers || {};
let loc = $json.redirect_url || headers.location || headers.Location || headers['content-location'] || '';

if (!loc) {
  const bodyStr = typeof $json.data === 'string' ? $json.data : JSON.stringify($json || {});
  const hrefMatch = bodyStr.match(/href=["'](https?:\/\/[^"']+)["']/i);
  if (hrefMatch) {
    loc = hrefMatch[1].replace(/&amp;/g, '&');
  } else {
    loc = (meta && meta.shopee_url) ? meta.shopee_url : '';
  }
}

loc = (loc || '').toString();

if (loc.startsWith('/')) {
  loc = 'https://shopee.co.id' + loc;
}

let isProduct = false;
let cleanShopeeUrl = loc;
let shopUrl = '';
let shopId = '';
let itemId = '';

try {
  const parsed = new URL(loc);
  const path = parsed.pathname;

  const dashMatch = path.match(/-i\.(\d+)\.(\d+)/);
  const prodSlashMatch = path.match(/\/product\/(\d+)\/(\d+)/);
  const slashMatch = path.match(/\/([^\/]+)\/(\d+)\/(\d+)/);

  if (dashMatch) {
    isProduct = true;
    shopId = dashMatch[1];
    itemId = dashMatch[2];
    cleanShopeeUrl = `https://shopee.co.id/product-i.${shopId}.${itemId}`;
    shopUrl = `https://shopee.co.id/shop/${shopId}`;
  } else if (prodSlashMatch) {
    isProduct = true;
    shopId = prodSlashMatch[1];
    itemId = prodSlashMatch[2];
    cleanShopeeUrl = `https://shopee.co.id/product-i.${shopId}.${itemId}`;
    shopUrl = `https://shopee.co.id/shop/${shopId}`;
  } else if (slashMatch && slashMatch[1] !== 'shop') {
    isProduct = true;
    shopId = slashMatch[2];
    itemId = slashMatch[3];
    cleanShopeeUrl = `https://shopee.co.id/product-i.${shopId}.${itemId}`;
    shopUrl = `https://shopee.co.id/shop/${shopId}`;
  } else if (path.startsWith('/product') && parsed.searchParams.has('itemId') && parsed.searchParams.has('shopId')) {
    isProduct = true;
    shopId = parsed.searchParams.get('shopId');
    itemId = parsed.searchParams.get('itemId');
    cleanShopeeUrl = `https://shopee.co.id/product-i.${shopId}.${itemId}`;
    shopUrl = `https://shopee.co.id/shop/${shopId}`;
  } else {
    isProduct = false;
    cleanShopeeUrl = `${parsed.origin}${path}`;
    shopUrl = cleanShopeeUrl;
  }
} catch (e) {
  cleanShopeeUrl = loc.split('?')[0];
  shopUrl = cleanShopeeUrl;
}

const intent = isProduct ? 'shopee_product' : 'shopee_shop';
const shopeeType = isProduct ? 'product' : 'shop';

const staticData = $getWorkflowStaticData('global');
staticData.currentResolved = {
  shopee_url: cleanShopeeUrl,
  shop_url: shopUrl,
  shop_id: shopId,
  item_id: itemId,
  resolved_url: cleanShopeeUrl,
  original_url: meta.original_url || meta.shopee_url,
  is_shortlink: true,
  shopee_type: shopeeType,
  intent: intent,
  chat_id: meta.chat_id,
  session_id: meta.session_id,
  user_name: meta.user_name,
  username: meta.username
};

if (staticData.sessions && staticData.sessions[meta.chat_id]) {
  if (isProduct) {
    staticData.sessions[meta.chat_id].total_product_scrapes = (staticData.sessions[meta.chat_id].total_product_scrapes || 0) + 1;
  } else {
    staticData.sessions[meta.chat_id].total_shop_scrapes = (staticData.sessions[meta.chat_id].total_shop_scrapes || 0) + 1;
  }
}

return [{
  json: {
    ...meta,
    shopee_url: cleanShopeeUrl,
    shop_url: shopUrl,
    shop_id: shopId,
    item_id: itemId,
    resolved_url: cleanShopeeUrl,
    original_url: meta.original_url || meta.shopee_url,
    is_shortlink: true,
    shopee_type: shopeeType,
    intent: intent
  }
}];
